import {useEffect, useState} from 'react';

import {configure, getConfig, subscribeConfigure} from '@gravity-ui/uikit';

import {i18n, languages} from '../i18n';
import type {AppLanguage} from '../i18n';

const fallbackLanguage: AppLanguage = 'en';

export function useAppLanguage() {
  const [language, setLanguage] = useState<AppLanguage>(() => {
    const configLanguage = getConfig().lang as AppLanguage;
    return languages.some(({code}) => code === configLanguage)
      ? configLanguage
      : fallbackLanguage;
  });

  useEffect(() => {
    const unsubscribe = subscribeConfigure((config) => {
      setLanguage(config.lang as AppLanguage);
